import java.util.Scanner; public class Main { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int t = sc.nextInt(); while (t-- > 0) { int greenCost = sc.nextInt(); int purpleCost = sc.nextInt(); int n = sc.nextInt(); int solved1 = 0; int solved2 = 0; for (int i = 0; i < n; i++) { solved1 += sc.nextInt(); solved2 += sc.nextInt(); } long option1 = (long) solved1 * greenCost + (long) solved2 * purpleCost; long option2 = (long) solved1 * purpleCost + (long) solved2 * greenCost; System.out.println(Math.min(option1, option2)); } sc.close(); } }